            operationId: string;
            /** @description 调用协议。 */
            protocol?: string | null;
            /** @description 请求方法。 */
            method?: string | null;
            /** @description 请求路径。 */
            path?: string | null;
            /** @description 访问结果。 */
            result: components["schemas"]["AccessResult"];
